import type { GitHubAdapter, GitHubPR, GitHubReview } from './adapter.js'

export interface PRState {
  pr: GitHubPR
  reviews: GitHubReview[]
}

export async function fetchPRState(
  github: GitHubAdapter,
  owner: string,
  repo: string,
  prNumber: number,
): Promise<PRState> {
  const [pr, reviews] = await Promise.all([
    github.getPullRequest({ owner, repo, number: prNumber }),
    github.getPullRequestReviews({ owner, repo, number: prNumber }),
  ])

  return { pr, reviews }
}

export function getLatestReview(reviews: GitHubReview[]): GitHubReview | null {
  const actionable = reviews.filter(
    (r) => r.state === 'APPROVED' || r.state === 'CHANGES_REQUESTED'
  )

  if (actionable.length === 0) return null

  return actionable.sort((a, b) => {
    const dateA = a.submitted_at ? new Date(a.submitted_at).getTime() : 0
    const dateB = b.submitted_at ? new Date(b.submitted_at).getTime() : 0
    return dateB - dateA
  })[0]
}

export function hasMaintainerApproval(reviews: GitHubReview[]): boolean {
  const maintainerRoles = ['COLLABORATOR', 'MEMBER', 'OWNER']
  return reviews.some(
    (r) =>
      r.state === 'APPROVED' &&
      maintainerRoles.includes(r.author_association)
  )
}

export async function fetchAllOpenPRs(
  github: GitHubAdapter,
  owner: string,
  repo: string,
  baseBranch: string,
): Promise<GitHubPR[]> {
  const allPRs: GitHubPR[] = []
  let page = 1
  const perPage = 100

  while (true) {
    const batch = await github.listPullRequests({
      owner,
      repo,
      state: 'open',
      base: baseBranch,
      page,
      perPage,
    })

    allPRs.push(...batch)

    if (batch.length < perPage) break
    page++
  }

  return allPRs
}

export async function fetchRecentClosedPRs(
  github: GitHubAdapter,
  owner: string,
  repo: string,
  limit: number = 50,
): Promise<GitHubPR[]> {
  return github.listPullRequests({
    owner,
    repo,
    state: 'closed',
    perPage: Math.min(limit, 100),
  })
}
